session_start(); require 'page-guard.php'; require '../config/db_conn.php'; require '../includes/csrf-token.php'; require '../includes/student-placement-options.php'; require '../includes/section-catalog-schema.php'; require 'components.php'; ensureSectionCatalogColumns($conn); seedDefaultTeacherSections($conn);
$conn->query("CREATE TABLE IF NOT EXISTS admin_security (ADMIN_USER VARCHAR(50) PRIMARY KEY, SECURITY_QUESTION VARCHAR(255) NOT NULL, SECURITY_ANSWER VARCHAR(255) NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");
$securityConfigured=false;$securityQuestion='';$security=$conn->prepare('SELECT SECURITY_QUESTION FROM admin_security WHERE ADMIN_USER=?');$security->bind_param('s',$_SESSION['admin-user']);$security->execute();if($row=$security->get_result()->fetch_assoc()){$securityConfigured=true;$securityQuestion=$row['SECURITY_QUESTION'];}
$groups=[];$rows=$conn->query("SELECT c.SECTION,c.GRADE,c.STRAND,c.IS_ACTIVE,COUNT(DISTINCT s.ID) students,COUNT(DISTINCT t.TEACHER_ID) teachers FROM sections c LEFT JOIN students s ON s.SECTION=c.SECTION LEFT JOIN teachers t ON t.SECTION=c.SECTION WHERE c.IS_ACTIVE=1 AND c.GRADE BETWEEN 7 AND 12 GROUP BY c.SECTION,c.GRADE,c.STRAND,c.IS_ACTIVE ORDER BY c.SECTION");while($row=$rows->fetch_assoc()){$groups[(int)$row['GRADE']][$row['STRAND']][]=$row;}
adminHead('Settings');adminSidebar('settings','Settings','Manage administrator security and grade-based teacher sections');
?>
