<div id="section-delete-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-slate-950/60 p-5"><div class="w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl"><h3 class="text-xl font-black text-slate-900">Delete section?</h3><p id="section-delete-message" class="mt-2 text-sm text-slate-500">This section will be removed if it has no linked students or teachers.</p><div class="mt-6 flex gap-3"><button type="button" id="cancel-section-delete" class="flex-1 rounded-xl border border-slate-300 px-4 py-3 font-bold">Cancel</button><button type="button" id="confirm-section-delete" class="flex-1 rounded-xl bg-rose-600 px-4 py-3 font-bold text-white">Delete</button></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.getElementById('section-delete-modal'),message=document.getElementById('section-delete-message');let pendingForm=null;document.querySelectorAll('button[value="delete_section"]').forEach(button=>{button.onclick=event=>{event.preventDefault();pendingForm=button.form;message.textContent=`Delete “${pendingForm.querySelector('[name="delete_target"]').value}”? This cannot be undone.`;modal.classList.replace('hidden','flex')}});document.getElementById('cancel-section-delete').onclick=()=>{pendingForm=null;modal.classList.replace('flex','hidden')};document.getElementById('confirm-section-delete').onclick=()=>{if(!pendingForm)return;pendingForm.querySelector('input[name="action"]').value='delete_section';pendingForm.submit()}});</script>
