ont-bold">Security question<select class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3" name="security_question" required><option value="What was the name of your first pet?">What was the name of your first pet?</option><option value="What city were you born in?">What city were you born in?</option><option value="What is your favorite teacher's surname?">What is your favorite teacher's surname?</option></select></label><label class="block text-sm font-bold">Answer<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" name="security_answer" autocomplete="off" required></label><button class="w-full rounded-xl bg-slate-900 px-5 py-3 font-bold text-white">Save security question</button></form></section>
<section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8 lg:col-span-2"><h2 class="text-xl font-black text-slate-900">Teacher sections</h2><p class="mt-1 text-sm text-slate-500">Open a grade to manage its sections. Grade 11 and Grade 12 are separated by strand.</p><div class="mt-5 flex gap-2"><input id="draft-section" class="min-w-0 flex-1 rounded-xl border border-slate-300 px-4 py-3" placeholder="New section name"><button type="button" id="open-add-section" class="rounded-xl bg-slate-900 px-4 py-3 font-bold text-white">Add</button></div><div class="mt-5 space-y-3"><?php foreach([7,8,9,10,11,12] as $grade): ?><details class="overflow-hidden rounded-xl border border-slate-200 bg-white"><summary class="cursor-pointer list-none px-4 py-4 font-bold text-slate-800 hover:bg-slate-50"><span class="flex items-center justify-between"><span>Grade <?= $grade ?></span><span class="text-sm font-normal text-slate-500">Click to manage sections</span></span></summary><div class="space-y-4 border-t border-slate-100 p-4"><?php $strands=$grade>=11?['Academic','Techpro']:[''];foreach($strands as $strand):$items=$groups[$grade][$strand]??[]; ?><div><?php if($strand): ?><h3 class="mb-2 text-sm font-black text-blue-700"><?= htmlspecialchars($strand) ?></h3><?php endif; ?><div class="space-y-2"><?php foreach($items as $item): ?><form action="settings-save.php" method="post" class="flex flex-wrap items-center gap-2 rounded-xl bg-slate-50 p-2"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="rename_section"><input type="hidden" name="old_section" value="<?= htmlspecialchars($item['SECTION']) ?>"><input type="hidden" name="delete_target" value="<?= htmlspecialchars($item['SECTION']) ?>"><input class="min-w-36 flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold" name="section" value="<?= htmlspecialchars($item['SECTION']) ?>"><span class="text-xs text-slate-500"><?= $item['students'] ?> students · <?= $item['teachers'] ?> teachers</span><button class="rounded-lg bg-blue-600 px-3 py-2 text-sm font-bold text-white">Save</button><button type="submit" name="action" value="delete_section" class="rounded-lg px-3 py-2 text-sm font-bold text-rose-600 hover:bg-rose-50" onclick="return confirm('Delete this section?')">Delete</button></form><?php endforeach; ?></div></div><?php endforeach; ?></div></details><?php endforeach; ?></div></section></div>
<div id="add-section-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-slate-950/60 p-5"><form action="settings-save.php" method="post" class="w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="add_section"><input id="new-section-value" type="hidden" name="section"><h3 class="text-xl font-black text-slate-900">Place new section</h3><p id="new-section-label" class="mt-2 text-sm text-slate-500"></p><label class="mt-5 block text-sm font-bold">Grade<select id="new-section-grade" class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3" name="grade" required><option value="">Choose a grade</option><?php foreach([7,8,9,10,11,12] as $grade): ?><option value="<?= $grade ?>">Grade <?= $grade ?></option><?php endforeach; ?></select></label><label id="new-section-strand-field" class="mt-4 hidden text-sm font-bold">Strand<select id="new-section-strand" class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3" name="strand"><option value="">Choose a strand</option><option>Techpro</option><option>Academic</option></select></label><div class="mt-6 flex gap-3"><button type="button" id="cancel-add-section" class="flex-1 rounded-xl border border-slate-300 px-4 py-3 font-bold">Cancel</button><button class="flex-1 rounded-xl bg-blue-600 px-4 py-3 font-bold text-white">Save section</button></div></form></div>
<script>const draft=document.getElementById('draft-section'),modal=document.getElementById('add-section-modal'),value=document.getElementById('new-section-value'),label=document.getElementById('new-section-label'),grade=document.getElementById('new-section-grade'),strandField=document.getElementById('new-section-strand-field'),strand=document.getElementById('new-section-strand');document.getElementById('open-add-section').onclick=()=>{const name=draft.value.trim();if(!name){draft.focus();return}value.value=name;label.textContent=`Assign “${name}” to a grade.`;modal.classList.replace('hidden','flex');grade.focus()};document.getElementById('cancel-add-section').onclick=()=>modal.classList.replace('flex','hidden');grade.onchange=()=>{const senior=grade.value==='11'||grade.value==='12';strandField.classList.toggle('hidden',!senior);strand.required=senior;if(!senior)strand.value=''};</script><?php adminFoot(); ?>
